using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace Folha {
static class Versions {
 static string Dir(Store s,string id){s.Dir(id);return Path.Combine(s.StateRoot,"versions",id);}
 public static object[] List(Store s,string id){var p=Dir(s,id);if(!Directory.Exists(p))return new object[0];return Directory.GetFiles(p,"*.json").OrderByDescending(f=>Path.GetFileName(f),StringComparer.Ordinal).Select(f=>(object)new{key=Path.GetFileNameWithoutExtension(f),time=long.Parse(Path.GetFileName(f).Substring(0,13))}).ToArray();}
 public static bool Due(Store s,string id){var p=Dir(s,id);if(!Directory.Exists(p))return true;var f=Directory.GetFiles(p,"*.json").OrderByDescending(x=>x,StringComparer.Ordinal).FirstOrDefault();return f==null||J.Now()-long.Parse(Path.GetFileName(f).Substring(0,13))>=300000;}
 public static void Save(Store s,Dictionary<string,object> d,bool force){var id=J.S(d,"id");var p=Dir(s,id);Directory.CreateDirectory(p);var files=Directory.GetFiles(p,"*.json").OrderByDescending(f=>f,StringComparer.Ordinal).ToArray();if(!force&&files.Length>0&&J.Now()-long.Parse(Path.GetFileName(files[0]).Substring(0,13))<300000)return;J.Atomic(Path.Combine(p,J.Now().ToString("D13")+"-"+J.Id()+".json"),J.Encode(d));foreach(var f in Directory.GetFiles(p,"*.json").OrderByDescending(f=>f,StringComparer.Ordinal).Skip(12)){if(Path.GetDirectoryName(Path.GetFullPath(f))!=Path.GetFullPath(p))throw new Exception("Versão inválida.");File.Delete(f);if(File.Exists(f+".bak"))File.Delete(f+".bak");}}
 public static string Restore(Store s,string id,string key){if(!System.Text.RegularExpressions.Regex.IsMatch(key,@"^\d{13}-[a-f0-9-]{36}$"))throw new Exception("Versão inválida.");var d=J.Parse(File.ReadAllText(Path.Combine(Dir(s,id),key+".json")));Store.Validate(d);if(J.S(d,"id")!=id)throw new Exception("Versão pertence a outro caderno.");var copy=J.Id();var original=s.Dir(id);d["id"]=copy;d["originId"]=id;d["name"]=J.S(d,"name")+" (versão recuperada)";d.Remove("deleted");d["revision"]=J.Id();d["updated"]=J.Now();Directory.CreateDirectory(s.Dir(copy));if(Convert.ToBoolean(d["pdf"]))File.Copy(Path.Combine(original,"source.pdf"),s.DataFile(copy,"source.pdf"));var images=Path.Combine(original,"assets");if(Directory.Exists(images)){Directory.CreateDirectory(Path.Combine(s.Dir(copy),"assets"));foreach(var f in Directory.GetFiles(images))File.Copy(s.DataFile(id,"assets/"+Path.GetFileName(f)),s.DataFile(copy,"assets/"+Path.GetFileName(f)));}s.Write(d);return copy;}
}
}
